import { Field, FieldControl, FieldDescription, FieldLabel } from "@/registry/erbium/ui/field";
import { Input } from "@/registry/erbium/ui/input";

export default function InputRequiredExample() {
  return (
    <Field required>
      <FieldLabel>Required field</FieldLabel>
      <FieldControl render={<Input placeholder="This field is required" />} />
      <FieldDescription>This field must be filled out.</FieldDescription>
    </Field>
  );
}

import InputRequiredExample from "../examples/input-required";

const Example = () => <InputRequiredExample />;

export default Example;
